"""
ランダムテストケース生成器 & ストレステスター (Stress Tester & Random Test Generator)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
解法コード (fast) と愚直解 (naive / brute-force) をランダムな小規模ケースで多数突合し、
WAになる最小のコーナーケースを自動特定するストレステストツール。

【使い方】
- gen_array(n, min_v, max_v): ランダム数列生成
- gen_tree(n): ランダムな木 (頂点数 n) の辺リストを生成
- gen_graph(n, m): ランダムな連結無向グラフを生成
- stress_test(solve_fast, solve_naive, generator, trials=100): ストレステスト実行
"""

import random

# https://github.com/ddfkit/acsampl/blob/main/testset.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def gen_array(n,low,high):
    return [random.randint(low,high) for _ in range(n)]

# https://github.com/ddfkit/acsampl/blob/main/testset.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def gen_tree(n):
    return [(i,random.randint(0,i-1)) for i in range(1,n)]

# https://github.com/ddfkit/acsampl/blob/main/testset.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def stress_test(fast_fn,naive_fn,gen_fn,trials=100):
    for t in range(trials):
        case=gen_fn()
        ans1=fast_fn(*case if isinstance(case,tuple) else (case,))
        ans2=naive_fn(*case if isinstance(case,tuple) else (case,))
        if ans1!=ans2:return False,case,ans1,ans2
    return True,None,None,None

if __name__ == "__main__":
    # 最大部分配列和のテスト例
    def fast(a):
        cur=mx=a[0]
        for x in a[1:]:cur=max(x,cur+x);mx=max(mx,cur)
        return mx

    def naive(a):
        return max(sum(a[i:j]) for i in range(len(a)) for j in range(i+1, len(a)+1))

    ok, bad_case, a1, a2 = stress_test(fast, naive, lambda: gen_array(6, -5, 5), trials=50)
    assert ok
    print("testset.py: tests passed!")
